const q=$input.first().json.query||{};
if(!/^\d+$/.test(String(q.listingId||''))||!Number.isSafeInteger(Number(q.listingId))||Number(q.listingId)<=0)throw new Error('A positive numeric listingId is required.');
if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(q.month||''))throw new Error('month must be YYYY-MM.');
const [y,m]=q.month.split('-').map(Number);
return [{json:{listingId:String(q.listingId),month:q.month,startDate:q.month+'-01',endDate:q.month+'-'+new Date(Date.UTC(y,m,0)).getUTCDate()}}];

const request=$('Validate request').first().json,pages=$input.all().map(x=>x.json);
if(!pages.length||pages.some(p=>p.status!=='success'||!Array.isArray(p.result)))throw new Error('Invalid reservation API response.');
if(pages.at(-1).result.length!==0)throw new Error('Pagination limit reached; incomplete results rejected.');
const reservations=[],seen=new Set();
for(const r of pages.flatMap(p=>p.result)){
 if(String(r.listingMapId)!==request.listingId)throw new Error('Hostaway returned a different listing.');
 if(seen.has(String(r.id)))continue;seen.add(String(r.id));
 if(!['new','modified'].includes(r.status))continue;
 const a=String(r.arrivalDate||'').slice(0,10),d=String(r.departureDate||'').slice(0,10);
 if(!/^\d{4}-\d{2}-\d{2}$/.test(a)||!/^\d{4}-\d{2}-\d{2}$/.test(d))throw new Error('Missing reservation dates for '+r.id);
 if(a<=request.endDate&&d>=request.startDate)reservations.push(r);
}
return [{json:{...request,reservations}}];

const request=$('Collect reservations').first().json;
const reservations=$input.all().map((item,i)=>{
 const r=$('Reservation items').itemMatching(i).json,p=item.json;
 if(p.status!=='success'||!Array.isArray(p.result))throw new Error('Invalid finance response for '+r.id);
 const fields=new Map();for(const f of p.result){if(Number(f.isDeleted)===1)continue;if(fields.has(f.name))throw new Error('Duplicate finance field '+f.name+' for '+r.id);fields.set(f.name,f);}
 const value=name=>{const v=fields.get(name)?.total;if(v==null||v===''||!Number.isFinite(Number(v)))return null;return Number(v);};
 // Missing fields stay null so the user can reconcile unsupported channels explicitly.
 return {id:String(r.id),listingId:String(r.listingMapId),guest:r.guestName||[r.guestFirstName,r.guestLastName].filter(Boolean).join(' ')||'Reservation '+r.id,checkIn:String(r.arrivalDate).slice(0,10),checkOut:String(r.departureDate).slice(0,10),channel:r.channelName||String(r.channelId),currency:r.currency,receipts:value('airbnbPayoutSum'),tax:value('airbnbPassThroughTax'),sourceExtras:value('reservationExpensesAndExtras'),source:'Hostaway finance',fetchedAt:new Date().toISOString()};
});
if(reservations.length!==request.reservations.length||new Set(reservations.map(r=>r.id)).size!==reservations.length)throw new Error('Missing or duplicate finance results.');
return [{json:{schemaVersion:1,listingId:request.listingId,month:request.month,property:request.reservations[0]?.listingName||'',reservations}}];
